CREATE OR REPLACE FUNCTION public.save_grn_draft(p_id uuid,p_version integer,p_payload jsonb) RETURNS public.grn_drafts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.grn_drafts; sid uuid:=public.current_store_id(); BEGIN IF sid IS NULL OR NOT public.can_manage_stock(auth.uid()) THEN RAISE EXCEPTION 'Not authorised'; END IF; IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid draft'; END IF; IF p_version=0 THEN INSERT INTO public.grn_drafts(id,store_id,created_by,payload) VALUES(coalesce(p_id,gen_random_uuid()),sid,auth.uid(),p_payload) RETURNING * INTO d; ELSE UPDATE public.grn_drafts SET payload=p_payload,version=version+1,updated_at=now() WHERE id=p_id AND store_id=sid AND version=p_version AND posted_grn_id IS NULL RETURNING * INTO d; IF NOT FOUND THEN RAISE EXCEPTION 'Draft changed or was already received. Reopen it before saving.'; END IF; END IF; RETURN d; END $$;